<?php
require_once dirname(__DIR__,3)."/includes/borrower_check.php";
require_once dirname(__DIR__,3)."/config/db.php";
require_once dirname(__DIR__,3)."/includes/activity_log_helper.php";
require_once dirname(__DIR__,3)."/includes/notification_helper.php";
require_once dirname(__DIR__,3)."/includes/request_helper.php";
require_once dirname(__DIR__,3)."/includes/adviser_endorsement_helper.php";
if(empty($_SESSION["csrf_token"]))$_SESSION["csrf_token"]=bin2hex(random_bytes(32));
$studentId=(int)$_SESSION["user_id"];$requestId=(int)($_GET["request_id"]??$_POST["request_id"]??0);
$load=function()use($pdo,$studentId,$requestId){$s=$pdo->prepare("SELECT rr.*,r.resource_name,r.resource_type,u.full_name AS adviser_name,u.department AS adviser_department FROM resource_requests rr JOIN resources r ON r.resource_id=rr.resource_id LEFT JOIN users u ON u.user_id=rr.adviser_user_id WHERE rr.request_id=:rid AND rr.borrower_id=:uid LIMIT 1");$s->execute([":rid"=>$requestId,":uid"=>$studentId]);return $s->fetch(PDO::FETCH_ASSOC);};
$request=$load();if(!$request||!gsoIsApprovedStudent($pdo,$studentId)){redirectWithFlash("my_requests.php","Adviser workflow request not found.");}
if($_SERVER["REQUEST_METHOD"]==="POST"){
 if(!hash_equals((string)$_SESSION["csrf_token"],(string)($_POST["csrf_token"]??""))){redirectWithFlash("adviser_request.php?request_id={$requestId}","Invalid request token.");}
 $action=(string)($_POST["action"]??"");
 try{
  $pdo->beginTransaction();$lock=$pdo->prepare("SELECT rr.*,r.resource_type FROM resource_requests rr JOIN resources r ON r.resource_id=rr.resource_id WHERE rr.request_id=:rid AND rr.borrower_id=:uid FOR UPDATE");$lock->execute([":rid"=>$requestId,":uid"=>$studentId]);$row=$lock->fetch(PDO::FETCH_ASSOC);if(!$row)throw new DomainException("Request not found.");
  if($action==="assign_adviser"){
   $adviserId=(int)($_POST["adviser_user_id"]??0);if((string)$row["adviser_state"]!=="Selection Required"||!empty($row["adviser_user_id"]))throw new DomainException("The Adviser can no longer be changed.");if(!gsoIsApprovedFaculty($pdo,$adviserId))throw new DomainException("Select an approved, verified Faculty account.");
   $u=$pdo->prepare("UPDATE resource_requests SET adviser_user_id=:aid,adviser_state='Pending Adviser' WHERE request_id=:rid AND borrower_id=:uid AND adviser_state='Selection Required' AND adviser_user_id IS NULL");$u->execute([":aid"=>$adviserId,":rid"=>$requestId,":uid"=>$studentId]);if($u->rowCount()!==1)throw new DomainException("The request changed. Refresh and try again.");$cycle=gsoNextAdviserCycle($pdo,$requestId);$pdo->prepare("INSERT INTO request_adviser_history(request_id,adviser_user_id,cycle_no,action,acted_by) VALUES(:rid,:aid,:cycle,'Submitted',:uid)")->execute([":rid"=>$requestId,":aid"=>$adviserId,":cycle"=>$cycle,":uid"=>$studentId]);
  }elseif($action==="resubmit_revision"){
   if((string)$row["adviser_state"]!=="Revision Required"||(int)$row["adviser_user_id"]<=0)throw new DomainException("This request is not available for revision.");$adviserId=(int)$row["adviser_user_id"];
   $quantity=(string)$row["resource_type"]==="Facility"?1:(int)($_POST["quantity"]??0);$contact=trim((string)($_POST["contact_number"]??""));$date=trim((string)($_POST["date_needed"]??""));$start=trim((string)($_POST["start_time"]??""));$end=trim((string)($_POST["end_time"]??""));$notes=trim((string)($_POST["notes"]??""));
   $errors=validateBorrowScheduleInputs((string)$row["resource_type"],$quantity,$date,$start!==""?$start:null,$end!==""?$end:null,null);if($contact===""||!preg_match('/^[0-9+\-\s()]{7,30}$/',$contact))$errors[]="Enter a valid contact number.";if($errors)throw new DomainException(implode(" ",$errors));
   $u=$pdo->prepare("UPDATE resource_requests SET quantity=:qty,contact_number=:contact,date_needed=:date,start_time=:start,end_time=:end,notes=:notes,adviser_state='Pending Adviser',status='Under Review' WHERE request_id=:rid AND borrower_id=:uid AND adviser_state='Revision Required' AND adviser_user_id=:aid");$u->execute([":qty"=>$quantity,":contact"=>$contact,":date"=>$date,":start"=>$start!==""?$start:null,":end"=>$end!==""?$end:null,":notes"=>$notes!==""?$notes:null,":rid"=>$requestId,":uid"=>$studentId,":aid"=>$adviserId]);if($u->rowCount()!==1)throw new DomainException("The request changed. Refresh and try again.");$cycle=gsoNextAdviserCycle($pdo,$requestId);$pdo->prepare("INSERT INTO request_adviser_history(request_id,adviser_user_id,cycle_no,action,acted_by) VALUES(:rid,:aid,:cycle,'Submitted',:uid)")->execute([":rid"=>$requestId,":aid"=>$adviserId,":cycle"=>$cycle,":uid"=>$studentId]);
  }else throw new DomainException("Invalid Adviser workflow action.");
  createNotification($pdo,$adviserId,"adviser_assignment","Endorsement Requested","Request REQ-".str_pad((string)$requestId,3,"0",STR_PAD_LEFT)." is waiting for your review.","endorsement_detail.php?request_id={$requestId}");addActivityLog($pdo,$studentId,"Adviser Request Submitted","Student routed request #{$requestId} to assigned Faculty adviser.");$pdo->commit();gsoSendAdviserAssignmentEmail($pdo,$requestId,$adviserId,$studentId);redirectWithFlash("my_requests.php","Request sent to your Adviser for endorsement.","success");
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();redirectWithFlash("adviser_request.php?request_id={$requestId}",$e instanceof DomainException?$e->getMessage():"The request could not be updated.");}
}
$history=gsoAdviserHistory($pdo,$requestId);$faculty=(string)$request["adviser_state"]==="Selection Required"?gsoFindEligibleFaculty($pdo,"",20):[];$pageTitle="Adviser Endorsement";$activePage="requests";require_once dirname(__DIR__,3)."/includes/header.php";require_once dirname(__DIR__,3)."/includes/borrower_sidebar.php";
?>
<div class="main-content"><?php require dirname(__DIR__,3)."/includes/borrower_topbar.php";?><main class="page-content"><section class="card"><h2>REQ-<?php echo str_pad((string)$requestId,3,"0",STR_PAD_LEFT); ?> — Adviser Endorsement</h2><p>Status: <strong><?php echo htmlspecialchars((string)$request["adviser_state"]); ?></strong></p><p>Resource: <?php echo htmlspecialchars((string)$request["resource_name"]); ?></p></section>
<?php if((string)$request["adviser_state"]==="Selection Required"): ?><section class="card"><h3>Select Adviser / Subject Teacher</h3><form method="post"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token']); ?>"><input type="hidden" name="request_id" value="<?php echo $requestId; ?>"><input type="hidden" name="action" value="assign_adviser"><label>Search approved Faculty <input type="search" id="facultySearch" placeholder="Search by name or department"></label><label>Adviser<select name="adviser_user_id" id="facultySelect" required><option value="">Select Faculty</option><?php foreach($faculty as $f):?><option value="<?php echo (int)$f['user_id']; ?>"><?php echo htmlspecialchars($f['full_name'].(!empty($f['department'])?' — '.$f['department']:'')); ?></option><?php endforeach;?></select></label><button class="admin-btn primary-btn">Submit to Adviser</button></form></section><script>const q=document.getElementById('facultySearch'),s=document.getElementById('facultySelect');let t;q.addEventListener('input',()=>{clearTimeout(t);t=setTimeout(()=>fetch('faculty_search.php?request_id=<?php echo $requestId;?>&q='+encodeURIComponent(q.value)).then(r=>r.json()).then(d=>{s.innerHTML='<option value="">Select Faculty</option>';(d.results||[]).forEach(x=>{const o=document.createElement('option');o.value=x.user_id;o.textContent=x.name+(x.department?' — '+x.department:'');s.appendChild(o);});}),250);});</script>
<?php elseif((string)$request["adviser_state"]==="Revision Required"): ?><section class="card"><h3>Revise and Resubmit</h3><p>The same Adviser remains assigned: <strong><?php echo htmlspecialchars((string)$request['adviser_name']); ?></strong></p><form method="post"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token']); ?>"><input type="hidden" name="request_id" value="<?php echo $requestId; ?>"><input type="hidden" name="action" value="resubmit_revision"><label>Quantity<input type="number" name="quantity" min="1" value="<?php echo (int)$request['quantity']; ?>"></label><label>Contact<input name="contact_number" value="<?php echo htmlspecialchars((string)$request['contact_number']); ?>" required></label><label>Date needed<input type="date" name="date_needed" value="<?php echo htmlspecialchars((string)$request['date_needed']); ?>" required></label><label>Start<input type="time" name="start_time" value="<?php echo htmlspecialchars((string)$request['start_time']); ?>"></label><label>End<input type="time" name="end_time" value="<?php echo htmlspecialchars((string)$request['end_time']); ?>"></label><label>Purpose / notes<textarea name="notes" maxlength="255"><?php echo htmlspecialchars((string)$request['notes']); ?></textarea></label><button class="admin-btn primary-btn">Resubmit to Same Adviser</button></form></section><?php else:?><section class="card"><p>Assigned Adviser: <?php echo htmlspecialchars((string)($request['adviser_name']??'Pending selection')); ?></p></section><?php endif; ?>
<section class="card"><h3>Endorsement History</h3><?php if(!$history):?><p>No endorsement events yet.</p><?php else:?><ul><?php foreach($history as $h):?><li>Cycle <?php echo (int)$h['cycle_no']; ?> — <?php echo htmlspecialchars($h['action']); ?> by <?php echo htmlspecialchars($h['actor_name']); ?><?php if($h['remarks']!==null):?>: <?php echo nl2br(htmlspecialchars($h['remarks'])); ?><?php endif;?></li><?php endforeach;?></ul><?php endif;?></section></main></div><?php require dirname(__DIR__,3)."/includes/footer.php";
